static TRAVEL_PLAN_MONTH_PICKS: &[(&str, &str)] = &[("september", "Greece, Croatia or Italy, because the sea is at its warmest now and the families have gone home, so the same room costs less"), ("february", "the Canaries or Cape Verde for proper sun, Venice for carnival, or Marrakesh for 20C days, and half term is the one week to book around"), ("november", "the Canaries, Egypt or Cape Verde for sun, or Rome, Prague and Budapest for cheap cities without queues"), ("december", "the Canaries or Cape Verde for sun, the Alps for snow, or any big European city for the Christmas markets - book before the middle of the month"), ("january", "the Canaries for 20C and real sun, the Alps for snow, or Seville for a city break in warmth, and the first week of January is the cheapest week of the year to fly"), ("october", "Cyprus or Crete for 24C and a sea you can still swim in, the Canaries for the most reliable sun, or Seville and Marrakesh for warm cities without the crowds"), ("august", "Scotland, Ireland, the Alps or Norway: the Mediterranean is at its busiest, hottest and priciest, and Italian and Spanish towns close up at midday"), ("march", "Marrakesh or Seville at about 20C, Rome and Florence before the queues start, or Lanzarote for reliable sun"), ("april", "Lisbon or Andalusia at 20C, Sicily before the heat arrives, or the tulips in the Netherlands, and Easter moves the prices"), ("june", "the Greek islands, the Algarve or the Baltic cities, and the first half of the month is quieter and cheaper than the second"), ("july", "Scotland or the Alps for cool walking, Norway and Denmark for cities, or the Atlantic coast of Portugal for a sea breeze - the Mediterranean is at its hottest now"), ("may", "Greece or Croatia before the crowds, the Algarve, or the Italian lakes, with the sea warm enough in the south by the end of the month")];
static TRAVEL_PLAN_MONTH_VERDICTS: &[(&str, &str)] = &[("september", "the best month of the year for most of Europe: the sea at its warmest, the families gone and the rooms cheaper"), ("february", "still low season, so cheap and quiet, with real sun only a few hours south and half term the week everyone else books"), ("november", "cheap and quiet with short days, and real sun only in the Canaries, Egypt or the Cape Verde islands"), ("december", "cold at home and festive in the cities, with sun a few hours south and the Christmas weeks to book early"), ("january", "good for sun or snow and the cheapest, quietest month of the year, but the Mediterranean is cold and half shut"), ("october", "still warm in the south with the crowds gone, though the north turns wet and some hotels shut for the winter"), ("august", "the busiest, hottest and priciest month of the year, so go north, go high or go early"), ("march", "spring arriving while the prices are still low, though the Mediterranean is mild rather than warm and Easter moves the cost"), ("april", "one of the best months for southern Europe - warm, quiet and cheaper than May - with Easter the week to book around"), ("june", "the sweet spot before the schools break up: hot, long days and prices that have not caught up with July"), ("july", "high season, so hot, busy and priced for it, and the Mediterranean coast is at its fullest"), ("may", "warm without the crowds, with the sea warm enough in the south by the end of it and the school holidays still a month away")];
static TRAVEL_PLAN_MONTH_SUN: &[(&str, &str)] = &[("september", "Greece, Croatia or southern Italy, 26-29C, with the sea at its warmest now the schools are back"), ("february", "the Canaries, Cape Verde or Egypt, all about 20 to 25C, and the Red Sea coast is the warmest water"), ("november", "the Canaries, Egypt or Cape Verde, and the Red Sea is the warmest of the three"), ("december", "the Canaries or Cape Verde for 25C, Egypt for 22C, or the Caribbean if you want guaranteed heat"), ("january", "the Canaries for 20C, Cape Verde for 25C, or Egypt for 22C and a sea you can swim in"), ("october", "Cyprus, Crete or the Canaries, 24-26C, and the sea is still swimmable"), ("august", "Portugal, Croatia or Greece, 28-31C and reliably dry, or the Baltic if 30C is too much"), ("march", "Lanzarote or the other Canaries for 20C, Marrakesh for 22C, or Dubai if you want 30C in the shade"), ("april", "the Algarve or Andalusia for 22C, Malta for 20C, or the Canaries to be sure of it"), ("june", "the Greek islands, Croatia or Sicily, 27-30C and the sea warm enough to swim"), ("july", "the Algarve, Croatia or the Greek islands, 28-31C, with the sea at its warmest"), ("may", "Greece, Cyprus or southern Spain, 24-27C, with the sea warming up and the prices before the school holidays")];
static TRAVEL_PLAN_HOME: &[(&str, &str)] = &[("yorkshire dales", "country"), ("great yarmouth", "coast"), ("brecon beacons", "country"), ("northumberland", "country"), ("isle of wight", "coast"), ("pembrokeshire", "coast"), ("lake district", "country"), ("peak district", "country"), ("the cotswolds", "country"), ("the highlands", "country"), ("isle of skye", "country"), ("bournemouth", "coast"), ("scarborough", "coast"), ("aberystwyth", "coast"), ("new forest", "country"), ("blackpool", "coast"), ("yorkshire", "country"), ("cotswolds", "country"), ("snowdonia", "country"), ("highlands", "country"), ("harrogate", "country"), ("cornwall", "coast"), ("anglesey", "coast"), ("brighton", "coast"), ("skegness", "coast"), ("bamburgh", "coast"), ("falmouth", "coast"), ("dartmoor", "country"), ("norfolk", "coast"), ("suffolk", "coast"), ("newquay", "coast"), ("st ives", "coast"), ("torquay", "coast"), ("brixham", "coast"), ("padstow", "coast"), ("exmouth", "coast"), ("cumbria", "country"), ("dorset", "coast"), ("sussex", "coast"), ("whitby", "coast"), ("exmoor", "country"), ("ludlow", "country"), ("devon", "coast"), ("gower", "coast"), ("tenby", "coast"), ("kent", "coast")];
static TRAVEL_PLAN_BEST: &[(&str, &str)] = &[("australia", "September to November and March to May for the south: warm, not scorching. December to February is 35C+ in Sydney and Melbourne, and the north is tropical wet season then."), ("portugal", "May, June and September: warm and dry with fewer people. July and August are hot and busy on the Algarve, and the north is wet from November to February."), ("thailand", "November to February: dry, warm and clear. March to May is hot and hazy, and June to October is the monsoon, when the islands get rough seas and some boats stop."), ("new york", "May to June and September to October: mild and walkable. July and August are hot and humid, January and February are cold with snow, and the Christmas weeks are the most expensive of the year."), ("scotland", "May to September for the Highlands, the islands and the long evenings. Midges are worst in July and August, and November to February has very short days."), ("iceland", "June to August gives midnight sun, open highland roads and puffins; February and March are best for the northern lights. November is dark, wet and icy, so it is the one month I would skip."), ("croatia", "June and September: the sea is warm and the coast is not yet rammed. July and August are the peak, and many islands shut down entirely from October."), ("morocco", "March to May and September to November: warm days, cool nights, no extreme heat. July and August are 40C+ inland, and the desert is cold at night all year."), ("greece", "May, June, September and early October: warm sea, open tavernas and no crush. August is 35C and the islands are packed, and many small hotels close from November to March."), ("turkey", "May, June and September for the coast, and April or October for Istanbul. July and August are hot and crowded, and the coast is quiet and mild in winter."), ("norway", "June to August for the fjords, the midnight sun and the coastal ferries. The northern lights need September to March and a clear, dark sky, and much of the mountain roads close in winter."), ("mexico", "November to April is the dry season, which is why it is the busy one. May to October is hot and wet, with rain usually in short afternoon storms."), ("spain", "April to June and September to October, when it is 20-28C and the coast is quiet. July and August are 35C+ inland and busy on the coast; the north stays green and cooler in summer."), ("italy", "April, May, late September and October: warm, not crowded, everything open. July and August are hot and packed, and August in the cities means half the restaurants shut."), ("japan", "Late March to April for the blossom, or October to November for the autumn colour. June is the rainy season, August is hot and humid, and the New Year week is the busiest travel period of the year."), ("dubai", "November to March, when it is 20-30C and you can be outside. From June to September it is over 40C, so people live in air conditioning and the hotel prices fall."), ("india", "October to March for most of the country: dry and cooler. April to June is brutally hot in the north, and the monsoon runs June to September."), ("usa", "It depends where: May and September for the northeast, spring and autumn for the southwest, and June to September for the national parks and mountains. Avoid the July 4th week and Thanksgiving for flights.")];
static TRAVEL_PLAN_WINDOWS: &[(&str, &str)] = &[("rio de janeiro", "December to March is hot, 28-32C, and Carnival falls in February or early March. May to October is cooler and drier, and the sea is still warm in September."), ("san sebastian", "June to September: 20-24C for the beach and the pintxos, with the film festival at the end of September. July and August are the busiest, and the rest of the year is wet."), ("san francisco", "September and October: the warmest, clearest months at 18-24C. July and August are foggy and cool, and the rain comes November to March."), ("lake district", "May, June and September for long clear days at 15-20C; September is the quietest dry-ish month and the fells are at their best. July and August bring the crowds to Windermere and the passes, and November to February is wet, dark and often icy on the tops."), ("buenos aires", "March to May and September to November: 18-25C and the parks at their best. December to February is hot and humid and the city empties in January, and July and August are cool and damp."), ("mexico city", "March to May: dry, warm and clear, before the rains. June to October is the wet season with short afternoon storms, and December to February is dry with cold nights."), ("los angeles", "March to May and September to November: 20-26C and clear. June to August is warm but the marine layer can sit all day at the beaches, and winter is mild with the odd storm."), ("copenhagen", "May to August: 18-22C, long days, and the harbour baths open from June. July is the busiest and the jazz festival, and November to February is dark by 4pm and cold."), ("edinburgh", "May, June and September: 15-20C, and daylight until nearly 11pm in June; August is the Festival and the Fringe, which is either why you go or when to avoid. November to February is dark by 4pm."), ("amsterdam", "April to June and September: 15-22C and the canals at their best, with the tulips at Keukenhof in late April. July and August are the busiest, and November to February is cold, wet and dark early."), ("ljubljana", "May, June and September: 20-26C, and Lake Bled is warm enough to swim from June. July and August are the busiest, and winter is cold and quiet."), ("stockholm", "May to August: 18-23C and light until late, with midsummer at the end of June. The archipelago is best from July to mid-August, and winter is dark with short days."), ("reykjavik", "June to August gives midnight sun, open highland roads and puffins; February and March are best for the northern lights. November is dark, wet and icy, so it is the one month I would skip."), ("barcelona", "May, June and September: 22-27C, the sea warm enough to swim and the terraces full. August is hot and packed, and November to February is cool with some rain."), ("santorini", "May, June, September and early October: 24-27C, warm sea and no crush. July and August are 30C+ with the cruise crowds landing mid-morning, and many hotels close from November to March."), ("dubrovnik", "May, June, September and early October: 22-27C and the city walls walkable. July and August are the peak and the cruise ships fill the old town by 10am, and winter is quiet."), ("singapore", "Any month works: it is 30C and humid all year, with rain in short bursts. February to April is the driest, November to January the wettest, and the haze can arrive in September."), ("marrakech", "March to May and October to November: 20-28C by day, cool at night, no extreme heat. July and August are 40C+ in the city, and the desert is cold at night all year."), ("cape town", "November to March: dry, 25-28C, the beaches and the Table Mountain cableway at their best. July and August are wet and windy, which is the whale season in Hermanus."), ("melbourne", "March to May and September to November: 18-24C, and the city is at its best in autumn. December to February is hot and changeable, and winter is cold and football."), ("yorkshire", "May to September: 16-20C, the Dales and the moors dry and open, and the coast best in June and September. The towns are busy at half term and in August, and the moors are bleak from November to February."), ("brussels", "May, June and September: 17-22C, and the Grand Place flower carpet in mid-August every second year. July and August are warm and quiet at weekends, and winter is grey and wet."), ("budapest", "April to June and September: 20-26C, and the thermal baths are good in cool weather too. July and August are 30C+, and December brings the Christmas markets along the Danube."), ("helsinki", "June to August: 18-23C with almost no night, and the archipelago ferries running. January and February are the coldest, with the best chance of snow, and December is dark."), ("florence", "April to June and September to October: 20-28C and the galleries without the August crush. July and August are 30C+ and busy, and winter means cool days and short queues."), ("valencia", "April to June and September to October: 20-26C, and the sea still swimmable in October. July and August are 30C+ and busy, and March is Las Fallas if you want the crowds."), ("istanbul", "April, May, September and October: 18-25C and dry, and the Bosphorus ferries at their best. July and August are hot and humid, and December to February is cold and wet."), ("new york", "May to June and September to October: mild and walkable at 20-26C. July and August are hot and humid, January and February are cold with snow, and the Christmas weeks are the most expensive of the year."), ("cornwall", "May, June and September: 16-20C, the coast path at its best and the lanes still quiet. July and August are the warmest weeks and the busiest by a long way, and October is mild and much emptier, with the Atlantic at its biggest."), ("tallinn", "June to August: 18-22C, the old town at its best and white nights in June. December to February is cold and snowy, and the Christmas market is one of the prettiest in Europe."), ("granada", "April to June and September to October: 18-28C, and the Alhambra bookable without a fight. July and August are 35C+ inland, and winter is cold up at the Alhambra."), ("seville", "March to May and October: 20-28C and the orange trees in flower or in fruit, with Semana Santa and the April fair the peak. July and August are 40C+, so people live at night."), ("bangkok", "November to February: dry, warm and clear, which is why it is the season. March to May is hot and hazy, and June to October is the monsoon with short, heavy afternoon rain."), ("chicago", "May, June and September: 20-27C and the lakefront at its best. July and August are hot and humid, and January and February are brutal with the wind off the lake."), ("toronto", "May to June and September to October: 18-25C. July and August are hot and humid, and December to March is cold with snow."), ("norfolk", "May to September: the Broads and the north Norfolk coast at 18-22C, and the seal trips running. July and August fill the coastal villages, and October to March is quiet, cheap and cold, with huge skies and good birdwatching."), ("london", "May, June and September: 18-22C and the long evenings. July and August are warm and crowded, and November to February is grey, wet and dark by 4.30pm."), ("dublin", "May, June and September: 16-20C and the longest days. July and August are the driest and busiest, and November to February is wet, with dark by 4.30pm."), ("munich", "May to September: 20-25C, beer gardens and the Alps an hour away; late September is Oktoberfest, which doubles hotel prices. December brings the Christmas markets."), ("zurich", "May to September for the lake, the old town and the mountain railways, at 22-26C in midsummer. December to February is cold and clear, which is when the Alps look their best."), ("berlin", "May to September: 20-25C, outdoor cafes, the lakes, and the city at its most relaxed. July and August are the warmest and busiest, and November to February is grey and cold."), ("prague", "April to June and September: 15-22C and the old town before the crush. July and August are busy and 25C+, and December is cold with the Christmas markets."), ("vienna", "April to June and September: 18-24C, and the ball season runs January to March. July and August are hot and the opera houses close, and December has the markets."), ("krakow", "May to September: 20-25C and the main square at its best; April and October are quiet and still fine. December to February is cold with snow and a Christmas market."), ("bergen", "May to September: 15-19C and the fjord trips running, with light until late in June and July. It rains most of the year, so pack a shell whatever the month."), ("venice", "April, May, late September and October: 18-24C, warm, not crowded and everything open. July and August are hot and packed, and November to January brings acqua alta."), ("naples", "April to June and September: 22-27C, with the ferries to Capri and the Amalfi coast running. July and August are hot and busy, and November to March is quiet and wet."), ("lisbon", "May, June and September: warm and dry with fewer people. July and August are hot and busy with the tourists, and November to February is wet, though milder than the north."), ("madrid", "April, May, June and September: 20-28C and dry, with the terraces out and the Prado quiet. July and August are 35C+ and the city empties, and winter is cold and clear."), ("athens", "April, May, October and early November: 20-26C and the sites walkable. July and August are 35C+ and the Acropolis is a scramble by 10am, and the islands are at their best in June and September."), ("havana", "November to April: dry and 24-28C. May to October is hot and wet, and August to October is hurricane season, though the rain usually comes in short afternoon storms."), ("sydney", "September to November and March to May: 20-26C, warm without the scorch. December to February is 30C+ and the beaches are packed, and June to August is mild, with whale watching."), ("mumbai", "November to February: dry, 25-30C and the most comfortable. March to June is hot and humid, and the monsoon runs June to September with heavy rain."), ("boston", "May, June, September and October: 18-26C, and October for the foliage. July and August are hot and humid, and January and February are cold with snow."), ("paris", "April to June and September to early October: 18-24C and the parks at their best. July and August are hot and many small restaurants close, and November to February is grey and cool."), ("milan", "April to June and September: 20-27C and the aperitivo season. July and August are hot and humid and the city half empties, and January is cold with the sales on."), ("porto", "May, June and September: 18-24C and dry, with the Douro valley at its best and the vines in leaf. July and August are warm and busy, and November to March is wet and grey."), ("crete", "May, June, September and early October: 24-28C and the sea warm, and the Samaria gorge opens in May. July and August are 30C+ and busy, and winter is mild on the south coast."), ("split", "May, June, September and early October: 22-27C, with the ferries to Hvar and Brac running. July and August are the peak and the old town is packed by day, and many islands shut from October."), ("zadar", "May, June and September: 22-27C and the sea warm enough to swim, with the Kornati islands as a day trip. July and August are busy, and winter is quiet."), ("tokyo", "Late March to April for the blossom, and October to November for the autumn colour and the clearest skies. June is the rainy season, August is hot and humid, and the New Year week closes many places."), ("kyoto", "Late March to early April for the blossom, and mid-November for the maples. July and August are hot and humid, and the New Year week is the busiest of the year."), ("hanoi", "October to December: 20-26C, dry and clear. January to March is cool and damp with drizzle, and May to September is hot and wet, with the heaviest rain in July and August."), ("dubai", "November to March, when it is 20-30C and you can be outside. From June to September it is over 40C, so people live in air conditioning and the hotel prices fall."), ("delhi", "October to March: dry and cooler, 15-25C. April to June is brutally hot at 40C+, and the monsoon runs July to September with flooding in some years."), ("devon", "May, June and September: 16-20C, both coasts open and the beaches half empty. Late July and August are the school-holiday crush on the sand and the roads, and October is still mild if you do not mind a shower."), ("bath", "May to September for the baths, the crescent and the canal; April and October are quieter and still fine. December is the Christmas market, which is the busiest weekend of the year."), ("oslo", "May to September: 18-23C, and the fjord islands are a ferry ride from the centre. June has the longest days, and November to February is cold and dark, with skiing an hour out of town."), ("rome", "April, May, late September and October: 20-26C and the ruins walkable. July and August are 30C+ with the fountains as the only relief, and August means half the restaurants shut.")];
