const COAT_NOT_ABOUT_TODAY: &[&str] = &["what coat", "what jacket", "which coat", "which jacket", "should i get", "should i buy", "worth it", "is it worth", "buy", "buying", "bought", "price", "cheap", "expensive", "best", "recommend", "shop", "sale", "size", "fits", "fit me", "too small", "too big", "outgrew", "needs a new", "need a new", "a new coat", "a new jacket", "new coat", "new jacket", "brand new", "zip", "zipper", "torn", "ripped", "stain", "smell", "store", "storage", "put away", "moth", "wash", "clean", "repair", "waterproof it", "reproof", "leak", "paint", "second coat", "coats of", "jacket potato", "potato", "antivirus", "laptop", "computer", "macbook", "city break", "weekend away", "holiday", "packing", "for the trip", "winter coat", "warm coat", "coat thats", "coat that is", "waterproof coat", "puffer", "ordered", "order", "medium", "small", "large", "arrived", "delivery", "wore", "worn", "inside out", "yesterday", "all day", "big enough", "long enough", "too long", "too short", "sleeves", "sleeve", "shoulders", "alter", "altering", "tailor"];
