const COOKING_GLOSSARY: &[cooking_cards::Term] = &[
    cooking_cards::Term { word: "reduce", reply: "Reducing is simmering a sauce uncovered until water boils off and it thickens and tastes stronger. Watch it at the end - the last two minutes do most of the work.", needs_definition: true, subjects: &["sauce", "stock", "gravy", "wine", "juice", "glaze", "syrup", "liquid", "broth", "soup", "half", "pan", "thicken", "thickens", "jam", "cream"] },
    cooking_cards::Term { word: "sear", reply: "Searing is browning meat hard in a hot pan, for flavour and colour, not for cooking it through. Pat it dry first and leave it alone until it releases by itself.", needs_definition: true, subjects: &["steak", "meat", "beef", "chicken", "fish", "salmon", "pork", "lamb", "tuna", "pan", "joint", "roast", "sausage", "tofu", "scallop"] },
    cooking_cards::Term { word: "blanch", reply: "Blanching is a minute or two in boiling water, then straight into cold water: it sets the colour of green vegetables and loosens tomato and peach skins.", needs_definition: false, subjects: &["vegetable", "vegetables", "greens", "bean", "beans", "broccoli", "tomato", "tomatoes", "peach", "almond", "almonds", "potato", "potatoes", "chips", "spinach", "cauliflower", "cabbage"] },
    cooking_cards::Term { word: "sweat", reply: "Sweating is softening onion or vegetables slowly in a little fat with the lid on, without colouring them. Low heat, five to ten minutes.", needs_definition: true, subjects: &["onion", "onions", "shallot", "shallots", "leek", "garlic", "carrot", "vegetables", "veg", "celery", "mushroom", "pan", "butter", "fat", "oil"] },
    cooking_cards::Term { word: "al dente", reply: "Al dente means pasta with a little bite left in the middle: take a minute off the packet time, taste it, and keep testing.", needs_definition: false, subjects: &[] },
    cooking_cards::Term { word: "fold", reply: "Folding is mixing gently with a big spoon, turning the bowl and cutting through, so you keep the air in whipped egg white or cream.", needs_definition: true, subjects: &["flour", "egg", "eggs", "white", "whites", "batter", "mixture", "dough", "cream", "sugar", "meringue", "ingredient", "ingredients", "pastry", "bowl", "spoon", "spatula", "filling", "chocolate"] },
    cooking_cards::Term { word: "deglaze", reply: "Deglazing is pouring wine, stock or water into a hot pan after frying and scraping the brown bits up: that is where the flavour is.", needs_definition: false, subjects: &["pan", "wine", "stock", "sauce", "bits", "meat", "roast", "gravy"] },
];
const SIDE_REPLIES: &[(&[&str], &str)] = &[
    (&["roast chicken", "roast dinner", "roasting chicken", "turkey", "whole chicken"], "Roast potatoes in the same oven for the last 45 minutes (boil them 10 minutes first, drain and shake them in hot oil and salt), and peas or greens with butter. Gravy from the tin is fine. If there is room, a tray of carrots, parsnips and onion can go in beside the bird, so the whole dinner comes out of one oven."),
    (&["sausages", "sausage", "bangers"], "Mash and onion gravy: boil the potatoes 15 minutes, mash them with butter and milk, and soften sliced onion in the sausage pan with a spoon of flour and a splash of stock for the gravy. Peas take 3 minutes, and the pan the sausages cooked in is the flavour."),
    (&["lamb", "lamb chops", "roast lamb"], "New potatoes with butter and mint, peas, and yoghurt stirred with chopped mint and lemon instead of mint sauce. Roast carrots and parsnips if the oven is on anyway; both take about 40 minutes beside the meat."),
    (&["steak", "beef", "roast beef"], "Chips and a sharp green salad, or a jacket potato if the oven is already on. Cook the steak last and rest it 5 minutes, then dress the salad in the pan with oil, vinegar and a spoon of mustard so nothing in it is wasted."),
    (&["salmon", "fish", "cod", "haddock", "fishcakes", "fish pie"], "New potatoes and peas, or rice with greens wilted in a pan with butter. A squeeze of lemon and yoghurt with chopped dill is all the sauce it needs, and both take less time than the fish."),
    (&["curry", "chilli", "daal", "dal", "dhal"], "Rice, and naan or a chapati if you have them. Grate cucumber, salt it for 10 minutes and squeeze it dry, then mix with yoghurt and cumin for a raita that cools the heat; mango chutney and coriander if they are in the cupboard."),
    (&["pasta", "spaghetti", "lasagne", "lasagna"], "Garlic bread and a green salad with a sharp dressing, because the salad is what cuts through the sauce. Tear the bread, rub it with garlic, oil and salt and give it 8 minutes in a hot oven while the pasta cooks."),
    (&["burger", "burgers", "hot dogs", "barbecue", "bbq"], "Coleslaw, chips and pickles: shred cabbage and carrot, salt it, squeeze it dry and mix it with mayonnaise and a splash of vinegar. Corn on the cob and a bowl of potato salad fill the same table without any more cooking."),
    (&["shepherds pie", "shepherd's pie", "cottage pie", "pie", "stew", "casserole"], "Peas or greens with butter, and bread and butter to mop the plate. A spoon of mustard or horseradish on the side cuts through a rich pie, and both take 5 minutes from frozen."),
    (&["soup", "broth"], "Bread and butter, or a cheese toastie cut in fingers for dipping. Something crunchy on top - toasted seeds, croutons, a handful of crisps - turns a bowl of soup into a meal."),
    (&["risotto", "paella", "pilaf"], "A green salad with lemon in the dressing, and bread. Keep the salad cold and sharp, since the rice is rich and soft, and put it on the table at the same time as the pan."),
    (&["chips", "fries", "french fries"], "Fish fingers, a fried egg or a burger, and something sharp with them: peas, pickles or coleslaw, or a chip butty with white bread, butter and vinegar."),
    (&["ham", "gammon", "pork"], "New potatoes, peas, and mustard or pickles: a spoon of mustard in the juices in the pan makes the sauce, and cabbage braised in butter fills the plate for very little."),
    (&["rice", "pilau", "basmati"], "Rice is the blank part of the plate, so it wants something wet and sharp with it: a curry, a daal, a chilli or a stir-fry, or grilled chicken with soy, ginger and lime. A spoon of yoghurt with mint or a squeeze of lemon on the rice itself makes the plainest meal taste finished."),
    (&["mash", "mashed potato", "baked potato", "jacket potato", "potato", "potatoes", "new potatoes", "boiled potatoes", "chips"], "Potatoes want something with juice on it: sausages and onion gravy, a pie, a stew, or a roast with the meat juices poured over. Peas, greens or a sharp pickle alongside stop it tasting flat, and for mash warm the plates and beat in butter and warm milk at the end."),
    (&["chicken", "chicken thighs", "chicken breast"], "Roast potatoes or mash, and something green with butter, plus a sauce made in the pan: splash in stock or wine, scrape the brown bits up and let it reduce for 2 minutes. That is a whole dinner from what is already on the hob."),
    (&["halloumi", "halloumi cheese"], "Halloumi is salty and squeaky, so it wants something juicy and sharp: tomatoes with lemon and herbs, couscous with chopped apricots, or a flatbread with yoghurt and a little chilli. Fry it dry in a hot pan for a minute a side and eat it straight away, while the middle is still soft."),
    (&["feta", "feta cheese"], "Feta is salty and crumbly, so it wants something sweet or juicy against it: watermelon, roasted peppers, tomatoes and cucumber with lemon and oregano, or a tray of roasted veg and chickpeas with feta crumbled over at the end. It does not melt, so add it last."),
    (&["corn on the cob", "sweetcorn", "corn"], "Butter, salt and pepper, and then the wet, sharp things next to it: coleslaw, a tomato and red onion salad with lime, or a spoon of chilli butter melted over the cobs. It sits beside a barbecue, a roast chicken or a bowl of chilli without any more cooking, and 2 minutes under a hot grill after boiling blisters the kernels."),
    (&["prawns", "prawn", "king prawns", "shrimp", "prawn linguine"], "Prawns take two minutes, so the rest is what you make first: garlic, chilli and butter in a pan with parsley, tossed through pasta or piled on toast, and a green salad or lemony courgette ribbons beside it. Bread to mop the pan is the best part."),
];
const SEASONING_REPLIES: &[(&[&str], &str)] = &[
    (&["roast lamb", "leg of lamb", "lamb chops", "lamb", "mutton"], "Rosemary, garlic and black pepper are the classic on lamb: push slivers of garlic and rosemary into a leg, or rub chops with oil, salt, crushed garlic and a pinch of cumin. Anchovy mashed into the rub, or a spoon of mint sauce stirred through yoghurt, is the other one that works. Salt the meat the night before if you have the time."),
    (&["roast beef", "steak", "beef", "brisket"], "Beef wants salt and coarse black pepper, and not much else: salt a steak 40 minutes before it goes in the pan, or rub a roast with mustard, thyme and horseradish before it goes in the oven. A spoon of horseradish in creme fraiche is the sauce, not the seasoning."),
    (&["roast chicken", "whole chicken", "chicken thighs", "chicken breasts", "chicken", "turkey"], "Lemon, garlic, thyme and paprika: rub the skin with oil, salt, lemon zest, crushed garlic and a spoon of paprika, and put half a lemon inside. For pieces, the same mix with cumin instead of paprika is what most traybakes want."),
    (&["pork", "pork chops", "belly pork", "gammon", "ham"], "Fennel seed, sage and black pepper are made for pork: crush the fennel, mix it with salt and rub it into the fat, and put sage leaves under the skin. A little mustard or cider in the pan at the end finishes it."),
    (&["salmon", "fish", "cod", "haddock", "trout"], "Fish takes lemon, dill and butter, and salt before it cooks rather than after: zest the lemon over it, lay dill on top and put a knob of butter on each piece. Paprika or fennel seed for a fillet that will be fried hard."),
    (&["tofu", "firm tofu", "silken tofu", "tempeh"], "Tofu has no salt or fat of its own, so it needs both: soy sauce, sesame oil, garlic and ginger, or a marinade it sits in for half an hour after being pressed. Fry it hard in a little oil first, until the edges are brown, and sauce it after - added wet, it steams and stays pale."),
    (&["halloumi", "feta"], "Chilli, lemon and oregano, with salt only if the cheese needs it: halloumi and feta are already salty, so they want heat and acid instead. Tofu wants soy, garlic and ginger before it goes in the pan, and a little cornflour to help it brown."),
    (&["ribs", "rack of ribs", "pork ribs", "spare ribs", "baby back ribs", "beef ribs"], "Ribs want sugar in the rub and acid in the sauce: brown sugar, paprika, salt, black pepper, garlic powder and a little cumin, rubbed on the night before or an hour ahead. Cook them low, covered, for two to three hours at 150C, then paint with barbecue sauce and finish them hot for ten minutes. The sugar is what makes the crust, and it burns above 200C, so sauce goes on late."),
    (&["potato", "potatoes", "new potatoes", "roast potatoes", "chips"], "Salt, oil and a herb that can take the heat: rosemary or thyme in the tray with the potatoes, and salt in the water they boil in, not only at the end. Paprika or garlic granules dusted on halfway through browning."),
    (&["rice", "pilau", "basmati", "couscous"], "Rice wants salt in the water, a bay leaf or a cardamom pod while it cooks, and butter or oil stirred through at the end. Cumin seeds fried in the oil first is what turns plain rice into pilau."),
    (&["tomatoes", "tomato", "cherry tomatoes", "passata"], "Tomatoes want salt, a little sugar if they are pale, and a herb that is not shy: basil torn in at the end for a salad, oregano or thyme in the pan for a sauce, and garlic cooked gently rather than browned. Salt them ten minutes before they go in and the juices come out and turn into the sauce."),
    (&["vegetables", "veg", "squash", "pumpkin", "butternut", "courgette", "courgettes", "carrots", "broccoli", "cauliflower", "aubergine"], "Roast veg wants salt, oil and heat, then something sharp at the end: lemon zest, a splash of vinegar or a crumble of feta. Cumin and paprika for squash and carrots, oregano and chilli for courgette and aubergine, and salt halfway through rather than only at the start."),
    (&["burger", "burgers", "sausage meat", "meatballs", "mince"], "Season the meat before it is shaped, not after: salt, black pepper and a little onion or mustard in the mix, then fry a spoonful to taste before you commit the lot. A burger needs nothing on the outside but salt, pepper and a hot pan."),
    (&["roast", "roast dinner", "roasting joint", "joint of meat"], "Salt the joint the night before if you can, then rub it with oil and pepper before it goes in: lemon, garlic and thyme for chicken, mustard and horseradish for beef, rosemary and garlic for lamb, fennel and sage for pork. Salt early is the one that makes the difference, because it gets into the meat instead of sitting on the skin."),
];
const DISH_PLAN_SIDES: &[(&str, &str)] = &[
    ("chicken thigh", "Potatoes tossed in the same tray save a pan; they need 40 minutes, so start them first."),
    ("cake", "Buttercream is 100g soft butter to 200g icing sugar, beaten with a splash of milk."),
    ("curry", "Rice, and naan or a chapati if you have them: a mug of rice to one and a half of water, 12 minutes with the lid on, and a spoon of yoghurt or raita beside it."),
    ("chips", "Fish fingers, a fried egg or a burger, and peas, pickles or coleslaw: something sharp cuts the fat."),
    ("spag bol", "Garlic bread and a green salad, and keep a mug of the pasta water back to loosen the sauce with."),
    ("lasagne", "Garlic bread and a green salad with a sharp dressing, because the salad is what cuts through the sauce: tear the bread, rub it with garlic, oil and salt and give it 8 minutes in a hot oven while the pasta cooks."),
    ("beef stew", "Mash, or dumplings dropped in for the last 25 minutes with the lid on."),
    ("chilli con carne", "Rice, or tortillas and a bowl of grated cheese and sour cream on the table."),
    ("fish pie", "New potatoes and peas, or rice with greens wilted in a pan with butter. A squeeze of lemon and yoghurt with chopped dill is all the sauce it needs, and both take less time than the fish."),
    ("pasta bake", "Garlic bread, rubbed with a cut clove and oiled, or a green salad with a sharp dressing: the bake is rich, so something crisp and acidic beside it is the whole job."),
    ("sunday roast", "Parboil the potatoes 8 minutes, shake them in the pan with hot fat and roast 40 to 45 minutes at 200C; greens take 5 minutes at the end, and the gravy wants the roasting tin on the hob with a spoon of flour and the stock."),
];
const PAIRING_A_TIME_OR_HEAT_ASK: &str = "\\b(how many minutes?|how many mins?|how long|how much time|minutes a side|mins a side|minutes per side|what temperature|what temp|what heat|gas mark|how do i time)\\b";
