const PAIRING_PAIRING_FOODS: &[&str] = &["cheese", "apples", "apple", "pear", "pears", "grapes", "fig", "figs", "penne", "fusilli", "macaroni", "rigatoni", "tagliatelle", "linguine", "gnocchi", "couscous", "quinoa", "halloumi", "lentils", "chickpeas", "sausages", "sausage", "ham", "salmon", "mackerel", "prawns", "tofu", "avocado", "tomatoes", "cucumber", "courgette", "aubergine", "beetroot", "sweet potato", "butternut", "hummus", "houmous", "yoghurt", "oats", "porridge", "eggs", "bacon", "chorizo", "steak", "chicken", "lamb", "pork", "duck", "turkey", "cod", "haddock", "tuna", "mushrooms", "peppers", "spinach", "broccoli", "cabbage", "peas", "beans", "carrots", "potatoes", "rice", "pasta", "noodles", "bread", "mash", "chips", "polenta", "wrap", "wraps", "pitta"];
