const DISH_SIDES: &[(&[&str], &str)] = &[
    (&["rice", "basmati", "pilau", "pilaf"], "Rice: 1 part rice to 1.5 parts water, 12 minutes with the lid on, then 10 minutes off the heat without lifting the lid."),
    (&["potato", "potatoes", "mash", "chips", "roasties"], "Potatoes: boil them for 15 to 20 minutes, or roast them at 200C for 40 to 45 minutes if you have the oven on anyway."),
    (&["salad", "slaw", "lettuce"], "A bag of leaves with a squeeze of lemon and a little oil is enough; dress it at the table so it does not go limp."),
    (&["bread", "naan", "pitta", "pita", "rolls", "garlic bread"], "Warm bread or a naan straight from the oven, no need for anything clever."),
    (&["veg", "vegetables", "greens", "broccoli", "beans", "peas", "carrots"], "Green vegetables: broccoli or beans steamed for 4 to 5 minutes, while everything else is on the table."),
    (&["gravy", "jus"], "Gravy: whisk a teaspoon of flour into the meat juices off the heat, then add stock and simmer it for 5 minutes, stirring the brown bits up. If it goes lumpy, push it through a sieve."),
];
const DISH_PLAN_WHEN_WORDS: &[&str] = &["tonight", "tomorrow", "today", "this evening", "this weekend", "this afternoon", "later", "on sunday", "on saturday", "on friday", "for dinner", "for tea", "for lunch", "for sunday", "for supper", "this week"];
