const HISTORY_PAST: &[history_cards::Record] = &[
    history_cards::Record { names: &["world war one", "world war 1", "ww1", "wwi", "first world war", "great war"], off: &["cause", "caused", "causes", "start", "started", "begin", "began", "trigger", "end", "ended", "over", "finish", "finished", "why", "won", "win", "winner", "beat", "victor", "victory", "prime minister", "leader", "president", "king", "emperor"], tell: "World War One ran from 1914 to 1918. It began when Archduke Franz Ferdinand was assassinated and the alliances pulled the great powers in, and it ended with Germany's armistice on 11 November 1918.",
 long: Some("World War One lasted four years and three months, from 28 July 1914 to the armistice on 11 November 1918."), dead: Some("About 17 million people died in World War One, roughly 9 to 10 million of them soldiers, and about 20 million more were wounded."), won: None, built: None, },
    history_cards::Record { names: &["world war two", "world war 2", "ww2", "wwii", "second world war"], off: &["cause", "caused", "causes", "start", "started", "begin", "began", "trigger", "end", "ended", "over", "finish", "finished", "why", "won", "win", "winner", "beat", "victor", "victory", "died", "die", "dead", "deaths", "death", "how many", "casualties", "killed", "prime minister", "leader", "president", "king", "emperor"], tell: "World War Two ran from 1939 to 1945. Britain and France declared war on Germany after it invaded Poland, and it ended with Germany's surrender on 8 May 1945 and Japan's on 2 September.",
 long: Some("World War Two lasted six years and a day, from 1 September 1939 to 2 September 1945."), dead: None, won: None, built: None, },
    history_cards::Record { names: &["samuel pepys", "pepys"], off: &[], tell: "Samuel Pepys (1633-1703) was a London naval administrator whose diary, kept from 1660 to 1669 in shorthand, is the best eyewitness account we have of the plague, the Great Fire and the Restoration court. He gave it up because he thought he was going blind, and it was not read until the 1820s.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["isambard kingdom brunel", "brunel"], off: &[], tell: "Isambard Kingdom Brunel (1806-1859) was the Victorian engineer of the Great Western Railway, the Clifton Suspension Bridge, the SS Great Britain and the Great Eastern, and the tunnels and viaducts between them. He worked at a scale nobody had tried before, in a top hat, and died at 53 after a stroke, worn out by the Great Eastern.",
 long: None, dead: Some("Brunel died on 15 September 1859, aged 53, of a stroke, ten days after the first, unsuccessful launch of the Great Eastern. He had been ill for most of that year and the ship's failures were blamed for it. He is buried at Kensal Green; the Royal Albert Bridge at Saltash, finished in the year he died, is his last work."), won: None, built: Some("Brunel built the Great Western Railway from London to Bristol, the Clifton Suspension Bridge over the Avon, the SS Great Britain (the first iron ship to cross the Atlantic under screw propeller), the Great Eastern, and the Box Tunnel and the viaducts and bridges along the GWR route. His last was the Royal Albert Bridge at Saltash, finished in the year he died."), },
    history_cards::Record { names: &["celts", "celtic people", "celtic britain", "ancient celts"], off: &["celtic fc", "celtic park", "football", "team", "match", "rangers", "language", "course", "class", "music", "song"], tell: "The Celts were the iron-working peoples of central Europe who spread west to Britain, Ireland, France and Spain from about 500 BC. They wrote nothing down themselves, so what is known comes from Roman writers and from their hillforts, torcs and burials - and from the Celtic languages still spoken in Wales, Scotland, Ireland and Cornwall.",
 long: None, dead: None, won: None, built: Some("The Celts built hillforts on high ground, with banks and ditches of earth and timber - Maiden Castle in Dorset is the largest in Britain - and lived in roundhouses of timber, wattle and thatch. They worked iron for swords, tools and ploughs, and fired pots without a wheel."), },
    history_cards::Record { names: &["egyptians", "ancient egyptians", "egyptian people"], off: &["pyramid", "pyramids", "mummy", "mummies", "mummify", "mummification", "pharaoh", "hieroglyph", "hieroglyphs", "cleopatra", "tutankhamun"], tell: "Ancient Egypt gave us the 365-day calendar, papyrus paper, hieroglyphic writing, glass and the water clock, and Egyptian surgeons were stitching wounds, setting broken bones and removing cataracts by about 2500 BC. Their maths was practical: fractions, a base of ten, and the 3-4-5 triangle for squaring a corner.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["domesday book", "domesday", "doomsday book", "doomsday"], off: &["doomsday clock", "prepper", "preppers", "film", "movie", "game", "song", "album"], tell: "The Domesday Book is the survey William the Conqueror ordered at Christmas 1085 and finished the next year: who held every manor, field, mill, wood and pig in England, and what each was worth before and after the Norman conquest. It was called Domesday because, like the Last Judgement, there was no appeal from it.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["normans invade", "norman invasion", "norman conquest", "normans came"], off: &[], tell: "The Normans invaded England in 1066: William of Normandy landed in September, killed King Harold at Hastings on 14 October, and was crowned on Christmas Day. Within twenty years his barons had built the castles and taken the land in the Domesday survey.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["edward the confessor"], off: &[], tell: "Edward the Confessor was king of England from 1042 to 1066, the last of the old West Saxon line: he rebuilt Westminster Abbey, where he is buried, and died childless in January 1066, which is why three men fought over the crown that year.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["admiral nelson", "horatio nelson", "lord nelson", "nelson"], off: &["mandela", "nelson mandela", "rugby", "new zealand", "city of nelson"], tell: "Horatio Nelson (1758-1805) was the British admiral who beat the French fleet at the Nile in 1798 and the combined French and Spanish fleet at Trafalgar in 1805, where he was shot and died on his own ship. He lost an arm and an eye in earlier actions and is remembered for the signal 'England expects that every man will do his duty'.",
 long: None, dead: Some("Nelson was shot by a French marksman on the quarterdeck of HMS Victory at Trafalgar on 21 October 1805, and died below decks about three hours later, with the battle already won. His body was put in a barrel of brandy for the sail home."), won: None, built: None, },
    history_cards::Record { names: &["richard the lionheart", "lionheart", "richard the first", "richard i"], off: &[], tell: "Richard I (1157-1199) was king of England for ten years and spent only about six months of them in England: he went on the Third Crusade, was captured on the way home and ransomed for a fortune, then died besieging a small castle in France.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["saladin"], off: &[], tell: "Saladin (about 1137-1193) was the Kurdish sultan who united Egypt and Syria and took Jerusalem back from the crusaders at Hattin in 1187. He fought Richard the Lionheart to a standstill in the Third Crusade and let the people of Jerusalem go rather than massacre them, which is why he is remembered well on both sides.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["suleiman the magnificent", "suleiman"], off: &[], tell: "Suleiman the Magnificent (1494-1566) ruled the Ottoman Empire for 46 years, took Belgrade and Rhodes, besieged Vienna in 1529, and gave the empire the law code that had him called Suleiman the Lawgiver at home. It was the height of Ottoman power.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["britain leave india", "britain left india", "british leave india", "british raj end", "british leave"], off: &[], tell: "Britain left India on 15 August 1947, when the country became independent and was partitioned into India and Pakistan at the same moment, which set off the largest migration and one of the worst episodes of violence of the century.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["neville chamberlain", "chamberlain"], off: &["job", "wages", "hiring"], tell: "Neville Chamberlain (1869-1940) was British prime minister from 1937 to 1940. He flew to Germany three times in 1938 and came back promising 'peace for our time' from Munich, gave up the Sudetenland, and was forced out after the Norway campaign in 1940.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["boer war", "boers"], off: &["memorial", "monument", "statue", "museum"], tell: "The Boer War ran from 1899 to 1902: the British fought the Dutch-speaking Boer republics of the Transvaal and the Orange Free State over gold and empire. It took a quarter of a million soldiers to win, and the camps where Boer families were held killed about 26,000 people, mostly children.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["franz ferdinand", "archduke ferdinand"], off: &["band", "song", "guitar", "the band"], tell: "Archduke Franz Ferdinand of Austria-Hungary was shot in Sarajevo on 28 June 1914 by Gavrilo Princip, a Bosnian Serb nationalist. Austria-Hungary blamed Serbia, the alliances pulled every great power in, and the First World War began five weeks later.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["russian revolution", "bolshevik revolution", "october revolution"], off: &[], tell: "The Russian Revolution ran through 1917: in February strikes and mutinies pushed the tsar to abdicate, and in October the Bolsheviks under Lenin took over in Petrograd. A civil war followed, the USSR was formed in 1922, and the last tsar was shot with his family in 1918.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["rasputin"], off: &["song", "boney m", "film"], tell: "Grigori Rasputin (1869-1916) was a Siberian peasant who became the tsarina's closest adviser because he seemed able to stop the haemophilia bleeding of the heir, Alexei. By 1916 his influence at court had become a scandal, and a group of nobles poisoned him, shot him and threw him in the Neva.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["attila the hun", "attila"], off: &[], tell: "Attila (about 406-453) was king of the Huns, the horsemen from the steppe who extracted tribute from the Roman Empire rather than taking it. He raided across the Balkans and into Gaul, was beaten at Chalons in 451, and died in 453 - after which his empire fell apart within a generation.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["pearl harbour", "pearl harbor"], off: &["film", "movie"], tell: "Japan attacked the US fleet at Pearl Harbor in Hawaii on 7 December 1941, sinking or damaging most of the battleships in a morning and killing about 2,400 people. The United States declared war the next day, which is how it entered the Second World War.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["otto von bismarck", "bismarck"], off: &["battleship", "ship", "herring"], tell: "Otto von Bismarck (1815-1898) was the Prussian statesman who united Germany in 1871 by three short wars and then ran it as chancellor until 1890. He called his method Realpolitik - what works rather than what is right - and built the welfare state and alliances that kept the peace in Europe for twenty years after he left.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["ireland become a republic", "ireland became a republic", "ireland a republic", "republic of ireland", "irish republic"], off: &["northern ireland", "holiday", "visit", "trip", "passport", "move to"], tell: "Ireland became a republic on 18 April 1949, when the Republic of Ireland Act came into force and the country cut its last constitutional link with the Crown. It had been the Irish Free State since 1922, after the war of independence and the treaty.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["the depression start", "the depression begin", "the depression happen", "the depression end", "the depression finish"], off: &[], tell: "The Great Depression began with the Wall Street crash in October 1929 and lasted through the 1930s: banks failed, a quarter of American workers lost their jobs, and world trade shrank by two thirds. It ended only with the rearmament that came with the Second World War.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["caesar augustus", "augustus", "octavian", "octavius", "first roman emperor"], off: &[], tell: "Augustus (63 BC-14 AD) was the first Roman emperor: Julius Caesar's adopted heir, who took the name Augustus when he came out on top of the civil wars in 27 BC and ruled for forty years. He kept the forms of the republic while holding the power of a king, and his reign opened the two centuries of peace Romans called the Pax Romana.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["women get the vote", "women got the vote", "women vote", "suffragettes", "suffrage", "votes for women", "woman get the vote", "women the vote"], off: &["america", "american", "usa", "in the us", "in the usa", "united states", "black", "african", "australia", "aus", "new zealand", "nz", "canada", "france", "germany", "india", "ireland", "switzerland", "south africa", "18", "16", "17", "21 year", "year olds", "year old", "age", "aged", "old", "young people", "younger", "teenagers", "teenager"], tell: "Women got the vote in Britain in two steps. In 1918 women over 30 who met a property test, and all men over 21, were given the vote; in 1928 women got it at 21, on the same terms as men. The suffragettes' campaign before the war, and women's work in the war, both pushed it through.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["slave trade", "slavery", "slaves"], off: &["britain", "british", "uk", "england", "english", "empire", "transatlantic", "america", "american", "usa", "us", "united states", "france", "french", "spain", "spanish", "portugal", "brazil", "india", "canada", "australia", "1865", "1807", "1833", "civil war", "bible", "god", "jesus", "church", "quran", "islam", "sin", "moral", "reparations", "museum"], tell: "It depends where: Britain banned the trade in 1807 and slavery in its colonies in 1833, France abolished it in 1848, the United States in 1865 with the 13th Amendment, and Brazil was last in 1888.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["slavery in america", "american slavery", "slavery in the us", "slavery in the united states", "america abolish slavery", "america abolished slavery", "us abolish slavery", "us abolished slavery", "thirteenth amendment", "13th amendment"], off: &[], tell: "The United States abolished slavery with the 13th Amendment, ratified in December 1865, after the Civil War. The Emancipation Proclamation of 1863 had freed slaves only in the rebel states, so the amendment was what ended it everywhere.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["rosa parks"], off: &[], tell: "Rosa Parks was the black seamstress in Montgomery, Alabama, who on 1 December 1955 refused to give up her bus seat to a white passenger. Her arrest set off the 381-day bus boycott led by a young Martin Luther King, and the Supreme Court struck down bus segregation the next year.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["charles dickens", "dickens"], off: &[], tell: "Charles Dickens (1812-1870) was the Victorian novelist who wrote Oliver Twist, A Christmas Carol, David Copperfield and Bleak House. He worked in a boot-polish factory as a boy, and that memory of child labour runs through his books, which were published in monthly parts and read aloud across the country.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["stalin", "joseph stalin", "josef stalin"], off: &["star trek", "or is it"], tell: "Joseph Stalin (1878-1953) ruled the Soviet Union from the late 1920s until he died. He forced through collectivisation of farming and crash industrialisation, at the cost of famines that killed millions, then led the country through the Second World War after Hitler invaded in 1941.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["lenin", "vladimir lenin"], off: &[], tell: "Vladimir Lenin (1870-1924) was the revolutionary who led the Bolsheviks to power in Russia in October 1917, pulled the country out of the First World War, and founded the Soviet state. He died in 1924 after a series of strokes, and Stalin took over the party machine.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["difference between ww1 and ww2", "difference between the world wars", "difference between world war one and world war two", "how were the world wars different", "ww1 and ww2 difference"], off: &[], tell: "World War One was mostly trench fighting in France and Belgium, and it ended with Germany intact and a peace the next war was blamed on. World War Two was a war of movement, bombing and genocide across Europe, Africa and the Pacific, it ended with both aggressors occupied, and it killed about four times as many people.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["vietnam war", "war in vietnam"], off: &[], tell: "The Vietnam War ran from 1955 to 1975, when North Vietnam and the Viet Cong beat South Vietnam and its American backers. It killed about 3 million people, more than half of them Vietnamese civilians.",
 long: Some("The Vietnam War ran about 20 years, from 1955 to the fall of Saigon on 30 April 1975; American combat troops were there from 1965 to 1973."), dead: None, won: None, built: None, },
    history_cards::Record { names: &["colosseum", "coliseum"], off: &["visit", "visiting", "worth seeing", "ticket", "tickets", "queue", "hotel", "crowds", "guided", "skip the line", "best time", "worth", "enough", "days", "whole day", "how long", "take"], tell: "The Colosseum was built in Rome between 72 and 80 AD, under the emperors Vespasian and Titus, with loot from the Jewish temple in Jerusalem. It held about 50,000 people for gladiator fights and animal hunts.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["tower of london"], off: &["visit", "visiting", "worth seeing", "ticket", "tickets", "queue", "hotel", "crowds", "guided", "skip the line", "best time"], tell: "The Tower of London was started by William the Conqueror in the 1070s, and later kings ringed it with walls and towers. It has been a fortress, a palace, a prison and a mint, and it holds the Crown Jewels.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["marshall plan"], off: &[], tell: "The Marshall Plan was the American programme that sent about 13 billion dollars to western Europe between 1948 and 1952 to rebuild after the war. It was offered to the Soviet Union and its neighbours as well, and Stalin refused.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["first president of the united states", "first president of the usa", "first president of america", "first us president", "first american president", "george washington", "first president of the us", "first president"], off: &["france", "french", "ireland", "irish", "mexico", "brazil", "india", "china", "russia", "south africa", "turkey", "israel", "egypt", "kenya", "nigeria", "ghana", "pakistan", "philippines", "korea", "singapore"], tell: "George Washington was the first president of the United States, from 1789 to 1797. The first electoral college chose him unanimously and he stepped down after two terms, which set the pattern every later president followed.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["last tsar of russia", "last tsar", "tsar nicholas", "nicholas ii", "tsar of russia", "nicholas the second"], off: &[], tell: "Nicholas II was the last tsar of Russia. He gave up the throne in March 1917 as the war and the bread queues broke his country, and he and his family were shot by the Bolsheviks in Yekaterinburg in July 1918.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["jfk", "john f kennedy", "john fitzgerald kennedy", "president kennedy", "kennedy"], off: &[], tell: "John F. Kennedy was the 35th US president, from 1961 until he was shot in Dallas on 22 November 1963. He faced the Soviet Union down over Cuba in 1962 and set the goal of landing a man on the moon before the decade was out.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["anne boleyn"], off: &[], tell: "Anne Boleyn was Henry VIII's second wife, from 1533 to 1536, and the mother of Elizabeth I. When she gave him no son he had her tried for adultery and executed at the Tower of London in May 1536.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["first emperor of china", "qin shi huang", "qin shihuang", "emperor of china"], off: &[], tell: "Qin Shi Huang was the first emperor of a united China, from 221 to 210 BC. He standardised writing, money and weights, joined up the Great Wall, and was buried with the terracotta army.",
 long: None, dead: None, won: None, built: None, },
];
const HISTORY_MADE: &[history_cards::Record] = &[
    history_cards::Record { names: &["aeroplane", "airplane", "first flight", "first plane"], off: &["fly", "flying", "flight", "flights", "airport", "luggage", "bag", "book", "ticket", "seat", "carry", "delay", "cancel", "turbulence", "scared", "afraid"], tell: "The Wright brothers, Orville and Wilbur, made the first powered aeroplane flight on 17 December 1903 at Kitty Hawk: 12 seconds and 36 metres. Their edge was working out how to control a wing, not just how to lift one.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["car", "cars", "automobile", "motor car"], off: &["my", "your", "our", "insurance", "mot", "tax", "lease", "hire", "buy", "buying", "second hand", "secondhand", "sell", "worth", "offer", "offering", "haggle", "haggling", "haggle over", "pay", "paying", "price", "prices", "cost", "costs", "how much should i pay", "deal", "dealer", "garage", "test drive", "finance", "part exchange", "part-exchange", "good", "best", "cheap", "cheapest", "affordable", "reliable", "recommend", "recommended", "advice", "new driver", "learner", "first time driver", "bought", "better", "cheaper", "sensible", "practical", "which", "should"], tell: "Karl Benz built the first car with a petrol engine in 1885 and patented it in 1886, and his wife Bertha drove it 100 km the next year to prove it worked. Henry Ford's Model T, from 1908, was the one that made cars ordinary.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["television", "tv"], off: &[], tell: "John Logie Baird gave the first public demonstration of television in London in 1926, using a spinning disc. Philo Farnsworth's all-electronic system, shown in 1927, is the one every modern set works on.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["steam engine", "steam engines"], off: &[], tell: "Thomas Newcomen built the first practical steam engine in 1712, to pump water out of mines, and James Watt improved it from 1769 with a separate condenser that wasted far less heat. Watt's engine is the one that powered the Industrial Revolution.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["electricity", "electric power"], off: &[], tell: "Nobody invented electricity: it is a force in nature, and people learned to make and use it over about 150 years. Franklin showed lightning was electric in 1752, Volta made the first battery in 1800, Faraday built the first generator in 1831, and Edison opened the first power station in 1882.",
 long: None, dead: None, won: None, built: None, },
    history_cards::Record { names: &["internet", "world wide web", "the web"], off: &[], tell: "No one person invented the internet: ARPANET linked four American university computers in 1969 and the network grew from there. Tim Berners-Lee invented the world wide web on top of it in 1989, at CERN, so documents could be linked.",
 long: None, dead: None, won: None, built: None, },
];
const HISTORY_DATE_LONG: &str = "(?i)\\b(?:how long|long|lasted)\\b";
const HISTORY_DATES: &[dates::Date] = &[
    dates::Date { names: &["eiffel tower", "eiffel"], off: &[], off_regex: None, tell: "The Eiffel Tower was finished in March 1889 for the Paris world's fair, the Exposition Universelle, and opened to the public in May that year. It is 300 metres to the top of the flagpole, was the tallest building in the world until 1930, and was meant to stand for twenty years.", long: None },
    dates::Date { names: &["penicillin", "fleming"], off: &["who discovered", "who found", "who invented", "who created"], off_regex: None, tell: "Alexander Fleming noticed the mould killing his bacteria at St Mary's Hospital in London in September 1928, and published it the next year. Howard Florey and Ernst Chain turned it into a medicine at Oxford in 1940-41, and the first patient was treated in 1941.", long: None },
    dates::Date { names: &["ice age", "ice ages", "last ice age", "glaciation", "glacial period"], off: &["film", "films", "movie", "mammoth", "the croods", "netflix", "cinema", "dvd", "sequel", "release"], off_regex: Some("(?i)\\bice ages?\\b(?:\\s+\\d|\\s+(?:out|on)\\b|\\s+(?:on|at) (?:tv|netflix|the cinema|bbc|itv|channel|disney))"), tell: "The last ice age ended about 11,700 years ago. The coldest part of it, the last glacial maximum, was about 20,000 years ago, when ice sheets reached as far south as the Thames and the Midlands.", long: Some("The last ice age ran for roughly 100,000 years and ended about 11,700 years ago, which is when the glaciers melted back and farming began. The coldest stretch was about 20,000 years ago.") },
    dates::Date { names: &["poll tax", "community charge"], off: &[], off_regex: None, tell: "The poll tax, officially the community charge, started in Scotland in April 1989 and in England and Wales in April 1990, and was replaced by the council tax in 1993. It charged every adult a flat amount instead of a rate on the value of the home, and the protests against it helped bring down Margaret Thatcher.", long: None },
    dates::Date { names: &["empire windrush", "windrush"], off: &[], off_regex: None, tell: "The Empire Windrush docked at Tilbury on 22 June 1948, bringing 1,027 passengers from the Caribbean, most of them Jamaican, who had answered an ad for workers in Britain. It was one ship among many, but the date became the shorthand for the start of that generation's arrival.", long: None },
    dates::Date { names: &["statue of liberty", "liberty island"], off: &[], off_regex: None, tell: "The Statue of Liberty was dedicated on 28 October 1886 in New York Harbour, a gift from France for the centenary of American independence. It was designed by Frederic Auguste Bartholdi with a iron frame by Gustave Eiffel, and the pedestal was paid for by public subscription.", long: None },
    dates::Date { names: &["nhs", "national health service"], off: &["dentist", "waiting", "prescription", "appointment", "gp", "job", "work for", "complaint", "complain", "charging", "charge", "private", "pay", "cost", "free", "eye", "eye test", "dental", "ambulance", "waiting list"], off_regex: None, tell: "The NHS started on 5 July 1948, when the National Health Service Act came into force in England and Wales under Aneurin Bevan, the health minister. It was the first health service anywhere to be free at the point of use and paid for out of taxation.", long: None },
];
